insert into public.kpis (id, proyecto_id, codigo, nombre, objetivo, ambito, categoria, formula, unidad, meta, meta_max, sentido, tolerancia, periodicidad, fuente, responsable, valor_manual, hito_id, adicional, justificacion)
  select id, proyecto_id, codigo, nombre, objetivo, ambito, categoria, formula, unidad, meta, meta_max, sentido, tolerancia, periodicidad, fuente, responsable, valor_manual, hito_id, adicional, justificacion from jsonb_populate_recordset(null::public.kpis, '[{"id":"d601b9de-5fa8-4c9c-a176-a4b8450e958b","proyecto_id":"933d77bd-1928-44c2-b2f9-800a8413c2e9","codigo":"KP01","nombre":"Avance del proyecto","objetivo":"Medir el progreso del trabajo total","ambito":"proyecto","categoria":"proyecto","formula":"trabajo_completado / trabajo_total * 100","unidad":"%","meta":45,"meta_max":null,"sentido":"mayor","tolerancia":10,"periodicidad":"Semanal","fuente":"Cálculo automático del sistema","responsable":"Camila Fuentes","valor_manual":null,"hito_id":null,"adicional":false,"justificacion":"Avance físico ponderado por duración (guía)."},{"id":"14b26090-03a8-478c-b398-79b06b31ec05","proyecto_id":"933d77bd-1928-44c2-b2f9-800a8413c2e9","codigo":"KP02","nombre":"Cumplimiento de hitos","objetivo":"Medir si los hitos se logran en la fecha comprometida","ambito":"hito","categoria":"proyecto","formula":"hitos_cumplidos_plazo / hitos_vencidos_o_completados * 100","unidad":"%","meta":90,"meta_max":null,"sentido":"mayor","tolerancia":20,"periodicidad":"Semanal","fuente":"Cálculo automático del sistema","responsable":"Camila Fuentes","valor_manual":null,"hito_id":null,"adicional":false,"justificacion":"Los hitos son los puntos de control del Directorio."},{"id":"2e6b539f-8e69-4cfb-9663-fcacf76cc59b","proyecto_id":"933d77bd-1928-44c2-b2f9-800a8413c2e9","codigo":"KP03","nombre":"Desviación de costos","objetivo":"Controlar el gasto contra lo planificado a la fecha","ambito":"proyecto","categoria":"proyecto","formula":"(costo_real - costo_planificado_fecha) / costo_planificado_fecha * 100","unidad":"%","meta":5,"meta_max":null,"sentido":"menor","tolerancia":5,"periodicidad":"Semanal","fuente":"Cálculo automático del sistema","responsable":"Camila Fuentes","valor_manual":null,"hito_id":null,"adicional":false,"justificacion":"Prioridad de Finanzas: proteger el presupuesto de $225M."},{"id":"7077825c-7670-42ef-b7ad-46e6425ac932","proyecto_id":"933d77bd-1928-44c2-b2f9-800a8413c2e9","codigo":"KP04","nombre":"Actividades atrasadas","objetivo":"Detectar atrasos temprano","ambito":"actividad","categoria":"proyecto","formula":"actividades_atrasadas / actividades_evaluadas * 100","unidad":"%","meta":10,"meta_max":null,"sentido":"menor","tolerancia":10,"periodicidad":"Semanal","fuente":"Cálculo automático del sistema","responsable":"Camila Fuentes","valor_manual":null,"hito_id":null,"adicional":false,"justificacion":"Alerta temprana antes del congelamiento de noviembre."},{"id":"ec6e5740-4428-4f18-9af8-eb1d7473b154","proyecto_id":"933d77bd-1928-44c2-b2f9-800a8413c2e9","codigo":"KP05","nombre":"Utilización de profesionales","objetivo":"Uso de la capacidad del equipo","ambito":"proyecto","categoria":"proyecto","formula":"horas_asignadas / horas_disponibles * 100","unidad":"%","meta":25,"meta_max":85,"sentido":"rango","tolerancia":10,"periodicidad":"Semanal","fuente":"Cálculo automático del sistema","responsable":"Camila Fuentes","valor_manual":null,"hito_id":null,"adicional":false,"justificacion":"Bajo 25 % hay capacidad ociosa; sobre 85 % hay riesgo de sobrecarga."},{"id":"19a9dfa7-97be-4d15-ae01-50b0dc6a2059","proyecto_id":"933d77bd-1928-44c2-b2f9-800a8413c2e9","codigo":"KP06","nombre":"Cumplimiento de actividades","objetivo":"Medir el cumplimiento de plazos de las actividades terminadas","ambito":"actividad","categoria":"proyecto","formula":"actividades_terminadas_plazo / actividades_terminadas * 100","unidad":"%","meta":85,"meta_max":null,"sentido":"mayor","tolerancia":10,"periodicidad":"Semanal","fuente":"Cálculo automático del sistema","responsable":"Camila Fuentes","valor_manual":null,"hito_id":null,"adicional":false,"justificacion":"Complementa el avance con la calidad del cumplimiento."},{"id":"9294da5d-b4f7-4a91-9a83-ba166848ce5d","proyecto_id":"933d77bd-1928-44c2-b2f9-800a8413c2e9","codigo":"KP07","nombre":"Índice de desempeño del cronograma (SPI)","objetivo":"Comparar trabajo ganado con trabajo planificado","ambito":"proyecto","categoria":"proyecto","formula":"valor_ganado / costo_planificado_fecha","unidad":"índice","meta":0.95,"meta_max":null,"sentido":"mayor","tolerancia":0.1,"periodicidad":"Semanal","fuente":"Cálculo automático del sistema","responsable":"Camila Fuentes","valor_manual":null,"hito_id":null,"adicional":true,"justificacion":"KPI adicional del equipo: valor ganado (EVM)."},{"id":"acf378e6-362f-43a7-9d96-a9b3c22e9bed","proyecto_id":"933d77bd-1928-44c2-b2f9-800a8413c2e9","codigo":"KP08","nombre":"Atraso del hito Go-Live","objetivo":"Proteger la fecha de paso a producción","ambito":"hito","categoria":"proyecto","formula":"H6_atraso_dias","unidad":"días hábiles","meta":0,"meta_max":null,"sentido":"menor","tolerancia":5,"periodicidad":"Semanal","fuente":"Cálculo automático del sistema","responsable":"Camila Fuentes","valor_manual":null,"hito_id":null,"adicional":true,"justificacion":"Desde noviembre no se permiten cambios de alto impacto."},{"id":"fe591788-0fa5-465d-a3db-fd08a473b573","proyecto_id":"933d77bd-1928-44c2-b2f9-800a8413c2e9","codigo":"KC01","nombre":"Tasa de aprobación de cambios","objetivo":"Equilibrio entre control y flexibilidad","ambito":"cambio","categoria":"cambio","formula":"cambios_aprobados / cambios_decididos * 100","unidad":"%","meta":50,"meta_max":85,"sentido":"rango","tolerancia":15,"periodicidad":"Semanal","fuente":"Cálculo automático del sistema","responsable":"Comité de cambios","valor_manual":null,"hito_id":null,"adicional":false,"justificacion":"Muy baja frena el negocio; muy alta indica falta de control de alcance."},{"id":"f57f437b-2ed8-4fc0-8c50-35d13786c28c","proyecto_id":"933d77bd-1928-44c2-b2f9-800a8413c2e9","codigo":"KC02","nombre":"Tiempo promedio de aprobación","objetivo":"Rapidez de decisión del comité","ambito":"cambio","categoria":"cambio","formula":"dias_promedi