","valor_manual":null,"hito_id":null,"adicional":false,"justificacion":"Protege la fecha de Go-Live."},{"id":"7bf24a3a-9fec-45de-bdde-225ea631f42e","proyecto_id":"933d77bd-1928-44c2-b2f9-800a8413c2e9","codigo":"KC06","nombre":"Implementación en plazo","objetivo":"Cambios cerrados a tiempo","ambito":"cambio","categoria":"cambio","formula":"cambios_cerrados_plazo / cambios_cerrados * 100","unidad":"%","meta":80,"meta_max":null,"sentido":"mayor","tolerancia":20,"periodicidad":"Semanal","fuente":"Cálculo automático del sistema","responsable":"Comité de cambios","valor_manual":null,"hito_id":null,"adicional":false,"justificacion":"Mide la capacidad de ejecutar lo aprobado."},{"id":"1fe809fe-704b-4eae-9f99-2508b8f707c1","proyecto_id":"933d77bd-1928-44c2-b2f9-800a8413c2e9","codigo":"KC07","nombre":"Efectividad del cambio","objetivo":"Cambios que lograron su objetivo","ambito":"cambio","categoria":"cambio","formula":"cambios_exitosos / cambios_cerrados * 100","unidad":"%","meta":80,"meta_max":null,"sentido":"mayor","tolerancia":10,"periodicidad":"Semanal","fuente":"Cálculo automático del sistema","responsable":"Comité de cambios","valor_manual":null,"hito_id":null,"adicional":false,"justificacion":"Paso 7 del flujo: evaluación y seguimiento."},{"id":"5132431a-fb41-4842-a233-359accaecaac","proyecto_id":"933d77bd-1928-44c2-b2f9-800a8413c2e9","codigo":"KC08","nombre":"Adopción del cambio","objetivo":"Uso real de lo implementado","ambito":"cambio","categoria":"cambio","formula":"adopcion_promedio","unidad":"%","meta":80,"meta_max":null,"sentido":"mayor","tolerancia":15,"periodicidad":"Semanal","fuente":"Cálculo automático del sistema","responsable":"Comité de cambios","valor_manual":null,"hito_id":null,"adicional":false,"justificacion":"Paso 10: adoptar el cambio en la cultura de la empresa."},{"id":"69e96960-653a-441d-bc42-3f1fba02c822","proyecto_id":"933d77bd-1928-44c2-b2f9-800a8413c2e9","codigo":"KC09","nombre":"Cumplimiento de etapas del flujo","objetivo":"Avance de los cam